package com.termux.app.workspace;
import org.json.*;import java.util.*;import java.util.regex.*;
/** Derived view of already loaded native history. Never opens a file or stores a transcript. */
final class ChatFileReferences {
 static final class Entry {final String key,message,sender;final JSONObject file;final long time;Entry(JSONObject row,JSONObject f,String from,long at){key=row.optString("key");message=row.optString("message");JSONObject copy;try{copy=new JSONObject(f.toString());}catch(Exception invalid){copy=new JSONObject();}file=copy;sender=from;time=at;}}
 private static final Pattern LINK=Pattern.compile("!?\\[([^\\]\\r\\n]{0,200})\\]\\((?:<([^<>\\r\\n]+)>|([^\\r\\n)]+))\\)");
 private static final Pattern UPLOAD=Pattern.compile("\\[TermuxJobs attachment:([a-f0-9]{32})\\]\\r?\\nName: ([^\\r\\n]{1,512})\\r?\\nFile: (/[^\\r\\n]+)\\r?\\nSize: ([0-9]+) bytes\\.");
 static List<Entry> collect(List<JSONObject> rows){
  Map<String,String> senders=new HashMap<>();Map<String,Long> times=new HashMap<>();for(JSONObject r:rows){String m=r.optString("message");if(Arrays.asList("user","agent").contains(r.optString("messageSender")))senders.put(m,r.optString("messageSender"));if(r.optString("kind").equals("user"))senders.put(m,"user");long at=timestamp(r.opt("messageTime"));JSONObject summary=r.optJSONObject("requestSummary");if(at==0&&summary!=null)at=timestamp(summary.opt("completedAt"));if(at>0)times.put(m,at);}
  LinkedHashMap<String,Entry> all=new LinkedHashMap<>();for(JSONObject r:rows){String kind=r.optString("kind"),from=senders.getOrDefault(r.optString("message"),"agent");long at=times.getOrDefault(r.optString("message"),0L);JSONArray nativeRefs=r.optJSONArray("fileReferences");if(nativeRefs!=null)for(int i=0;i<nativeRefs.length();i++){JSONObject f=nativeRefs.optJSONObject(i);if(f!=null)add(all,r,f,f.optString("sender",from),at);}
   JSONObject a=r.optJSONObject("attachment");if(a!=null){if(a.optString("id").matches("[a-f0-9]{32}"))from="user";add(all,r,a,from,at);}
   if(kind.equals("text")){Matcher m=LINK.matcher(r.optString("body"));while(m.find()){String p=m.group(2)==null?m.group(3):m.group(2);try{if(p.startsWith("/"))p=ChatAttachmentUi.localPath(p);else if(!remoteFile(p,m.group(1)))continue;add(all,r,new JSONObject().put("name",(p.startsWith("/")?new java.io.File(p).getName():android.net.Uri.parse(p).getLastPathSegment())).put("path",p).put("type",ChatAttachments.type(p)).put("localFileLink",true).put("catalogResolved",true),"agent",at);}catch(Exception ignored){}}}
   if(kind.equals("user")){Matcher m=UPLOAD.matcher(r.optString("body"));while(m.find()){String p=m.group(3);if(!p.contains("/chat-attachments/"+m.group(1)+"/")||!new java.io.File(p).getName().matches("[A-Za-z0-9_.-]{1,100}"))continue;try{add(all,r,new JSONObject().put("id",m.group(1)).put("name",m.group(2)).put("path",p).put("bytes",Long.parseLong(m.group(4))).put("type",ChatAttachments.type(p)).put("localFileLink",true).put("catalogResolved",true),"user",at);}catch(Exception ignored){}}}
  }return new ArrayList<>(all.values());
 }
 private static void add(Map<String,Entry> all,JSONObject row,JSONObject f,String from,long at){try{f=new JSONObject(f.toString());if(f.optBoolean("localFileLink")&&!f.optBoolean("catalogResolved")&&f.optString("path").startsWith("/")){String path=ChatAttachmentUi.localPath(f.getString("path"));f.put("path",path).put("name",new java.io.File(path).getName()).put("catalogResolved",true);}}catch(Exception invalid){return;}String path=f.optString("path",f.optString("url"));if(path.isEmpty())return;String key=row.optString("message")+"\0"+path;if(!all.containsKey(key))all.put(key,new Entry(row,f,from,at));else if(!all.get(key).file.has("bytes")&&f.has("bytes"))try{all.get(key).file.put("bytes",f.get("bytes"));}catch(JSONException ignored){}}
 static boolean remoteFile(String value,String label){try{android.net.Uri uri=android.net.Uri.parse(value);if(!Arrays.asList("http","https").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||value.matches(".*[\\s\\p{Cntrl}].*"))return false;String path=uri.getPath();if(path==null||path.contains("/blob/")||path.contains("/tree/"))return false;String name=new java.io.File(path).getName();return name.matches("(?i).+\\.(png|jpe?g|gif|webp|bmp|avif|mp4|mkv|webm|mov|pdf|zip|7z|tar|gz|xz|stl|blend|obj|glb|gltf|apk|txt|log|json|csv|docx?|xlsx?|pptx?)")||name.matches("(?i).+\\.html?")&&label.equals(name);}catch(Exception ignored){return false;}}
 static long timestamp(Object raw){if(raw instanceof Number){long n=((Number)raw).longValue();return n>0?n:0;}if(raw instanceof String)try{return java.time.Instant.parse((String)raw).toEpochMilli();}catch(Exception ignored){}return 0;}
}
